-- 0162 · the privacy policy says what the site actually does, and says it in five languages.
--
-- Its test is supabase/tests/108_privacy_gaps.sql (rolled back):
--   node --env-file=.env scripts/db-dry-run.mjs supabase/migrations/0162_privacy_gaps.sql supabase/tests/108_privacy_gaps.sql
--
-- The external review of 2026-10-25 (F10) said the policy did not cover the land form's documents and
-- coordinates, the visit bookings or the assistant, and had no retention schedule. Checking it found two
-- more things it had no way to see from outside:
--
--   · legal.privacy_email WAS EMPTY. The policy ends «أكتبلنا على البريد اللي في آخر الصفحة» and there was
--     no address at the end of the page. A right to be forgotten with no way to ask for it is not a right.
--
--   · THE WHOLE POLICY WAS ARABIC ONLY. Not one of the nine sections had a translation, so a French, German,
--     Italian or English reader was shown the Arabic. The site has run in five languages since 0109, and
--     /abroad exists to sell to Tunisians who have lived abroad long enough to read one of the other four.
--     The site sweep could not catch this: Arabic prose is valid text, not a missing key.
--
-- AND ONE SENTENCE WAS NO LONGER TRUE. «موقعك» promised that location is computed on the phone and never
-- reaches us. That is right for the app's «قدّاش يبعد عليّ؟» and wrong for the landowner form, which sends
-- latitude and longitude with the offer — the review spotted exactly this. The section now separates them,
-- because a privacy policy that is accurate about one feature and wrong about another is worse than one
-- that is vague about both.
--
-- THE RETENTION PERIODS BELOW ARE OPERATIONAL CHOICES, NOT LEGAL ADVICE, and the Back Office description
-- says so. The ones tied to contracts and accounting stay as «what the law requires» because inventing a
-- number there would be worse than naming none; the rest — a conversation with the assistant, a hashed IP,
-- a visit booking — have no legal minimum and are given one so the policy means something. The owner
-- confirms them with whoever advises him.

update public.settings
   set value = to_jsonb('contact@agrized.site'::text)
 where key = 'legal.privacy_email';

update public.settings set value = to_jsonb(to_char((now() at time zone 'Africa/Tunis')::date, 'YYYY-MM-DD'))
 where key = 'legal.privacy_updated_at';

-- ---------------------------------------------------------------------------
-- The policy itself
-- ---------------------------------------------------------------------------

create temp table _priv (locale text primary key, body jsonb) on commit drop;

insert into _priv values ('ar', $json$[
 {"title":"شنوّة نجمعو","body":"كي تعمّر مطلب اهتمام: الاسم والكنية، نمرة التلفون، البريد الإلكتروني (اختياري)، الولاية والمعتمدية، شنوّة تحبّ تعمل وعدد الزيتونات اللي تهمّك، وأي ملاحظة تكتبها.\nكي تحجز أو تمضي عقد: رقم بطاقة التعريف والعنوان، وهي لازمة للعقد نفسه.\nكي تفتح حساب «زيتونتي»: نمرة التلفون وكلمة سرّ مشفّرة. ما نشوفوش كلمة السرّ متاعك.\nكي تعرض علينا أرض: اسمك ونمرتك، وين تلقى الأرض ومساحتها وثمنها اللي تطلبو، والوثائق اللي ترفعها، وإحداثيات الأرض كان اخترتها على الخريطة.\nكي تحجز زيارة بالفيديو: اسمك ونمرة الواتساب، والنهار والوقت اللي اخترتو، وأي ملاحظة تكتبها.\nكي تسأل المساعد: السؤال اللي كتبتو والجواب، وبصمة مشفّرة لعنوان IP.\nكي تقبل الإشعارات في التطبيق: رمز الجهاز اللي يسمحلنا نبعثولك إشعار. ما فيه لا اسم لا نمرة.\nفي كل الحالات: تاريخ وساعة العملية، ونوع المتصفّح، وبصمة مشفّرة لعنوان IP — للأمان وللتثبّت من المطالب، موش للإشهار."},
 {"title":"موقعك","body":"فمّا زوز حالات مختلفين، ونحبّو نوضّحوهم:\nفي التطبيق، كان تنقر على «قدّاش يبعد عليّ؟» في صفحة عرض، نطلبو من التلفون موقعك باش نحسبو البعد بينك وبين الأرض. الحساب يتعمل في التلفون متاعك، والموقع ما يوصلناش: ما نسجّلوهش عندنا وما نبعثوهش لحتّى جهة. نطلبوه كان وقت ما تكون في التطبيق، وتنجم ترفض والتطبيق يخدم عادي.\nأمّا في فورمولير «عندك أرض ولا ضيعة؟»، كان حطّيت أرضك على الخريطة ولا نقرت «أنا في الأرض توّا»، إحداثيات الأرض **توصلنا وتتسجّل** مع العرض — خاطر ما ننجّموش ندرسو أرض ما نعرفوش وين هي. هذي إحداثيات الأرض اللي تعرضها، موش موقعك إنت، وتنجم تكتب العنوان بالكلام عوض الخريطة."},
 {"title":"وثائق الأراضي","body":"الوثائق اللي ترفعها مع عرض الأرض تتخزّن في فضاء **مسكّر**: ما عندها حتى رابط عمومي، وما ينجّم يسردها ولا يحمّلها كان الموظّف المخوّل في AgriZed (القانوني والمالي والمسؤول الفلاحي والإدارة). ما ننشروهاش، وما نبعثوهمش لحتّى جهة أخرى.\nنقبلو PDF وJPG وPNG برك، وفمّا حدّ للحجم. كي تطلب مسحهم، نمسحوهم كان ما كانش علينا موجب قانوني نحتفظو بيهم."},
 {"title":"المساعد في الموقع","body":"كي تسأل المساعد، السؤال متاعك يتبعث لمزوّد الذكاء الاصطناعي باش يجاوبك، ونحتفظو بالسؤال والجواب عندنا باش نحسّنو الخدمة ونحميوها من الاستعمال المفرط.\nما تكتبش في المساعد معطيات حسّاسة — رقم بطاقة التعريف، كلمة سرّ، معلومات بنكية. كان تحبّ تحكي على ملفّك، كلّمنا مباشرة ولا ادخل لـ«زيتونتي»."},
 {"title":"علاش نجمعوها","body":"باش نتصلو بيك على المطلب اللي بعثتو، نحسبولك تقدير، نحضّرو ونتابعو العقد والأقساط، نبعثولك رسائل وإشعارات على ملفّك، ونحميو الموقع من المطالب الوهمية. ما نستعملوش معطياتك باش نبيعولك حاجة أخرى، وما نبيعوهمش لحتّى حدّ."},
 {"title":"مع من نشاركوها","body":"ما نبيعو معطياتك لحتّى جهة. نشاركوها كان مع المزوّدين اللي يخدمو معانا باش الخدمة تمشي: مزوّد الاستضافة وقاعدة البيانات، مزوّد الرسائل القصيرة باش توصلك الرسالة، خدمة الإشعارات متاع Expo كي تقبل الإشعارات، ومزوّد الذكاء الاصطناعي كي تسأل المساعد. كل واحد منهم ياخذ كان القدّ اللي يلزمو. زيد على هذا، كان إذا طلبتها جهة قضائية بصفة قانونية."},
 {"title":"قدّاش نحتفظو بيها","body":"العقود والدفوعات: المدّة اللي تفرضها الالتزامات القانونية والمحاسبية.\nمطالب الاهتمام وملفّات الحرفاء: مدّة العلاقة التجارية، وبعدها نمسحو كان ما كانش فمّا موجب قانوني.\nعروض الأراضي ووثائقها: حتى يتقرّر في العرض، وسنة بعدها.\nحجوزات الزيارات: سنتين.\nمحادثات المساعد: 90 يوم.\nبصمات عناوين IP: 12 شهر، وهي مشفّرة وما تدلّش على شخص بوحدها.\nرمز إشعارات التطبيق: يتمسح كي تشيل التطبيق ولا توقّف الإشعارات.\nكي تطلب المسح ونكونو ما عندناش موجب قانوني نحتفظو، نمسحو معطياتك."},
 {"title":"حقوقك","body":"تنجم تطلب تشوف المعطيات اللي عندنا عليك، تصلّحها، ولا تمسحها، وتنجم ترجع في موافقتك على الاتصال بيك في أي وقت. أكتبلنا على البريد اللي في آخر الصفحة ونجاوبوك."},
 {"title":"الأطفال","body":"الخدمة موجّهة للكبار. ما نجمعوش معطيات عن الأطفال بمعرفتنا، وكي يوصلنا إلي عملنا هكا، نمسحوها."}
]$json$::jsonb);

insert into _priv values ('fr', $json$[
 {"title":"Ce que nous collectons","body":"Demande d'intérêt : nom et prénom, téléphone, e-mail (facultatif), gouvernorat et délégation, ce que vous souhaitez faire et le nombre d'oliviers qui vous intéresse, ainsi que vos remarques.\nRéservation ou contrat : numéro de CIN et adresse, nécessaires au contrat lui-même.\nCompte « Zitounti » : téléphone et mot de passe chiffré. Nous ne voyons pas votre mot de passe.\nOffre de terrain : votre nom et votre téléphone, l'emplacement du terrain, sa superficie et le prix demandé, les documents que vous téléversez, et les coordonnées du terrain si vous les choisissez sur la carte.\nVisite vidéo : votre nom et votre numéro WhatsApp, le jour et l'heure choisis, et vos remarques.\nAssistant du site : votre question et la réponse, ainsi qu'une empreinte chiffrée de l'adresse IP.\nNotifications dans l'application : l'identifiant de l'appareil, qui ne contient ni nom ni numéro.\nDans tous les cas : date et heure, type de navigateur, et une empreinte chiffrée de l'adresse IP — pour la sécurité et la vérification des demandes, pas pour la publicité."},
 {"title":"Votre position","body":"Deux cas différents, que nous tenons à distinguer :\nDans l'application, si vous touchez « À quelle distance ? » sur la page d'une offre, nous demandons votre position au téléphone pour calculer la distance. Le calcul se fait sur votre téléphone : la position ne nous parvient pas, nous ne l'enregistrons pas et ne la transmettons à personne. Nous ne la demandons que lorsque l'application est ouverte, et vous pouvez refuser.\nEn revanche, dans le formulaire « Vous avez un terrain ? », si vous placez le terrain sur la carte ou touchez « je suis sur le terrain », les coordonnées du TERRAIN **nous parviennent et sont enregistrées** avec l'offre — nous ne pouvons pas étudier une parcelle que nous ne savons pas situer. Ce sont les coordonnées du terrain proposé, pas les vôtres, et vous pouvez écrire l'adresse en toutes lettres à la place."},
 {"title":"Les documents fonciers","body":"Les documents joints à une offre de terrain sont stockés dans un espace **privé** : aucun lien public, et seuls les employés autorisés d'AgriZed (juridique, finance, responsable agricole et direction) peuvent les lister ou les télécharger. Nous ne les publions pas et ne les transmettons à aucun tiers.\nNous acceptons uniquement PDF, JPG et PNG, dans une limite de taille. À votre demande, nous les supprimons, sauf obligation légale de conservation."},
 {"title":"L'assistant du site","body":"Lorsque vous interrogez l'assistant, votre question est transmise à un fournisseur d'intelligence artificielle pour y répondre, et nous conservons la question et la réponse afin d'améliorer le service et de le protéger des abus.\nN'écrivez pas de données sensibles à l'assistant — numéro de CIN, mot de passe, informations bancaires. Pour parler de votre dossier, contactez-nous directement ou connectez-vous à « Zitounti »."},
 {"title":"Pourquoi nous les collectons","body":"Pour vous rappeler au sujet de votre demande, établir une estimation, préparer et suivre le contrat et les échéances, vous envoyer les messages et notifications relatifs à votre dossier, et protéger le site des demandes fictives. Nous n'utilisons pas vos données pour vous vendre autre chose et nous ne les vendons à personne."},
 {"title":"Avec qui nous les partageons","body":"Nous ne vendons vos données à personne. Nous les partageons uniquement avec les prestataires nécessaires au fonctionnement du service : l'hébergeur et la base de données, le fournisseur de SMS, le service de notifications Expo lorsque vous les acceptez, et le fournisseur d'intelligence artificielle lorsque vous interrogez l'assistant. Chacun ne reçoit que le strict nécessaire. En dehors de cela, uniquement sur demande légale d'une autorité judiciaire."},
 {"title":"Durées de conservation","body":"Contrats et paiements : la durée imposée par les obligations légales et comptables.\nDemandes d'intérêt et dossiers clients : la durée de la relation commerciale, puis suppression en l'absence d'obligation légale.\nOffres de terrain et leurs documents : jusqu'à la décision sur l'offre, puis un an.\nRéservations de visite : deux ans.\nConversations avec l'assistant : 90 jours.\nEmpreintes d'adresses IP : 12 mois ; elles sont chiffrées et n'identifient personne à elles seules.\nIdentifiant de notifications : supprimé lorsque vous désinstallez l'application ou désactivez les notifications.\nÀ votre demande, et en l'absence d'obligation légale de conservation, nous supprimons vos données."},
 {"title":"Vos droits","body":"Vous pouvez demander à consulter les données que nous détenons sur vous, les corriger ou les supprimer, et retirer à tout moment votre consentement à être contacté. Écrivez-nous à l'adresse figurant en bas de cette page."},
 {"title":"Les enfants","body":"Le service s'adresse à des adultes. Nous ne collectons pas sciemment de données concernant des enfants ; si cela venait à notre connaissance, nous les supprimerions."}
]$json$::jsonb);

insert into _priv values ('en', $json$[
 {"title":"What we collect","body":"Interest request: your name, phone number, e-mail (optional), governorate and delegation, what you would like to do and how many olive trees interest you, and any note you write.\nReservation or contract: your ID card number and address, which the contract itself requires.\n«Zitounti» account: your phone number and an encrypted password. We never see your password.\nOffering us land: your name and number, where the land is, its area and the price you are asking, the documents you upload, and the land's coordinates if you pick them on the map.\nVideo visit: your name and WhatsApp number, the day and time you chose, and any note.\nThe site assistant: your question and its answer, and a hashed fingerprint of your IP address.\nApp notifications: the device token, which carries no name and no number.\nIn every case: the date and time, the browser type, and a hashed fingerprint of the IP address — for security and for checking requests, not for advertising."},
 {"title":"Your location","body":"Two different cases, which we want to keep apart:\nIn the app, if you tap «how far is it?» on an offer, we ask the phone for your location to work out the distance. The calculation happens on your phone: the location does not reach us, we do not store it and we pass it to nobody. We ask only while the app is open, and you may refuse.\nIn the «Do you have land?» form, however, if you place the land on the map or tap «I am on the land now», the LAND's coordinates **do reach us and are stored** with the offer — we cannot study a plot we cannot locate. These are the coordinates of the land being offered, not yours, and you may type the address in words instead."},
 {"title":"Land documents","body":"Documents attached to a land offer are kept in **private** storage: there is no public link, and only authorised AgriZed staff (legal, finance, the agricultural manager and management) can list or download them. We do not publish them and we pass them to no third party.\nWe accept PDF, JPG and PNG only, within a size limit. On request we delete them, unless we are legally required to keep them."},
 {"title":"The site assistant","body":"When you ask the assistant a question, it is sent to an AI provider to be answered, and we keep the question and the answer to improve the service and protect it from abuse.\nDo not type sensitive details into the assistant — ID number, password, bank details. To discuss your file, contact us directly or sign in to «Zitounti»."},
 {"title":"Why we collect it","body":"To call you back about your request, work out an estimate, prepare and follow the contract and its instalments, send you the messages and notifications about your file, and protect the site from fake requests. We do not use your details to sell you anything else, and we sell them to nobody."},
 {"title":"Who we share it with","body":"We sell your data to nobody. We share it only with the providers the service needs to run: the hosting and database provider, the SMS provider, the Expo notification service when you accept notifications, and the AI provider when you use the assistant. Each receives only what it needs. Beyond that, only on the lawful request of a judicial authority."},
 {"title":"How long we keep it","body":"Contracts and payments: as long as legal and accounting obligations require.\nInterest requests and client files: for the length of the commercial relationship, then deleted where no legal obligation applies.\nLand offers and their documents: until the offer is decided, then one year.\nVisit bookings: two years.\nAssistant conversations: 90 days.\nIP fingerprints: 12 months; they are hashed and identify nobody on their own.\nNotification token: deleted when you uninstall the app or turn notifications off.\nOn request, and where no legal obligation applies, we delete your data."},
 {"title":"Your rights","body":"You may ask to see the data we hold about you, to correct it or to delete it, and you may withdraw your consent to be contacted at any time. Write to us at the address at the bottom of this page."},
 {"title":"Children","body":"The service is for adults. We do not knowingly collect data about children, and if we learn that we have, we delete it."}
]$json$::jsonb);

insert into _priv values ('de', $json$[
 {"title":"Was wir erheben","body":"Interessenanfrage: Name, Telefonnummer, E-Mail (optional), Gouvernorat und Delegation, was Sie vorhaben und wie viele Olivenbäume Sie interessieren, sowie Ihre Anmerkungen.\nReservierung oder Vertrag: Ausweisnummer und Anschrift, die der Vertrag selbst benötigt.\n«Zitounti»-Konto: Telefonnummer und ein verschlüsseltes Passwort. Ihr Passwort sehen wir nie.\nGrundstücksangebot: Ihr Name und Ihre Nummer, Lage, Fläche und geforderter Preis, die hochgeladenen Dokumente sowie die Koordinaten des Grundstücks, wenn Sie sie auf der Karte wählen.\nVideobesichtigung: Name und WhatsApp-Nummer, gewählter Tag und Uhrzeit, Anmerkungen.\nAssistent: Ihre Frage und die Antwort sowie ein gehashter Fingerabdruck der IP-Adresse.\nApp-Benachrichtigungen: die Gerätekennung, die weder Namen noch Nummer enthält.\nIn allen Fällen: Datum und Uhrzeit, Browsertyp und ein gehashter Fingerabdruck der IP-Adresse — zur Sicherheit und zur Prüfung von Anfragen, nicht für Werbung."},
 {"title":"Ihr Standort","body":"Zwei verschiedene Fälle, die wir auseinanderhalten:\nIn der App fragen wir beim Tippen auf «Wie weit ist es?» den Standort ab, um die Entfernung zu berechnen. Die Berechnung erfolgt auf Ihrem Telefon: der Standort erreicht uns nicht, wird nicht gespeichert und an niemanden weitergegeben. Wir fragen nur bei geöffneter App, und Sie dürfen ablehnen.\nIm Formular «Haben Sie ein Grundstück?» hingegen erreichen uns die Koordinaten des GRUNDSTÜCKS **und werden gespeichert**, wenn Sie es auf der Karte setzen oder «Ich bin auf dem Grundstück» tippen — ein Grundstück, das wir nicht verorten können, können wir nicht prüfen. Es sind die Koordinaten des angebotenen Grundstücks, nicht Ihre, und Sie können stattdessen die Adresse schreiben."},
 {"title":"Grundstücksdokumente","body":"Dokumente zu einem Grundstücksangebot liegen in einem **privaten** Speicher: kein öffentlicher Link, und nur berechtigte AgriZed-Mitarbeiter (Recht, Finanzen, Agrarleitung und Geschäftsführung) können sie auflisten oder herunterladen. Wir veröffentlichen sie nicht und geben sie an keinen Dritten weiter.\nWir akzeptieren nur PDF, JPG und PNG innerhalb einer Größenbeschränkung. Auf Wunsch löschen wir sie, sofern keine gesetzliche Aufbewahrungspflicht besteht."},
 {"title":"Der Assistent","body":"Wenn Sie den Assistenten fragen, wird Ihre Frage zur Beantwortung an einen KI-Anbieter übermittelt; Frage und Antwort bewahren wir auf, um den Dienst zu verbessern und vor Missbrauch zu schützen.\nGeben Sie dem Assistenten keine sensiblen Daten — Ausweisnummer, Passwort, Bankdaten. Für Ihr Dossier wenden Sie sich direkt an uns oder melden Sie sich bei «Zitounti» an."},
 {"title":"Warum wir sie erheben","body":"Um Sie zu Ihrer Anfrage zurückzurufen, eine Schätzung zu erstellen, Vertrag und Raten vorzubereiten und zu begleiten, Ihnen Nachrichten und Benachrichtigungen zu Ihrem Vorgang zu senden und die Website vor Scheinanfragen zu schützen. Wir nutzen Ihre Daten nicht, um Ihnen etwas anderes zu verkaufen, und verkaufen sie an niemanden."},
 {"title":"Mit wem wir sie teilen","body":"Wir verkaufen Ihre Daten an niemanden. Wir teilen sie nur mit den Dienstleistern, die der Betrieb erfordert: Hosting und Datenbank, SMS-Anbieter, der Expo-Benachrichtigungsdienst, wenn Sie Benachrichtigungen annehmen, und der KI-Anbieter, wenn Sie den Assistenten nutzen. Jeder erhält nur das Nötige. Darüber hinaus nur auf rechtmäßiges Verlangen einer Justizbehörde."},
 {"title":"Aufbewahrungsfristen","body":"Verträge und Zahlungen: solange gesetzliche und buchhalterische Pflichten es verlangen.\nInteressenanfragen und Kundenakten: für die Dauer der Geschäftsbeziehung, danach Löschung, sofern keine gesetzliche Pflicht besteht.\nGrundstücksangebote und ihre Dokumente: bis zur Entscheidung über das Angebot, danach ein Jahr.\nBesichtigungsbuchungen: zwei Jahre.\nGespräche mit dem Assistenten: 90 Tage.\nIP-Fingerabdrücke: 12 Monate; sie sind gehasht und identifizieren für sich genommen niemanden.\nBenachrichtigungskennung: gelöscht, wenn Sie die App deinstallieren oder Benachrichtigungen abschalten.\nAuf Ihren Wunsch und ohne gesetzliche Aufbewahrungspflicht löschen wir Ihre Daten."},
 {"title":"Ihre Rechte","body":"Sie können Auskunft über die zu Ihnen gespeicherten Daten verlangen, sie berichtigen oder löschen lassen und Ihre Einwilligung zur Kontaktaufnahme jederzeit widerrufen. Schreiben Sie uns an die Adresse am Ende dieser Seite."},
 {"title":"Kinder","body":"Der Dienst richtet sich an Erwachsene. Wir erheben wissentlich keine Daten über Kinder; erfahren wir davon, löschen wir sie."}
]$json$::jsonb);

insert into _priv values ('it', $json$[
 {"title":"Cosa raccogliamo","body":"Richiesta di interesse: nome e cognome, telefono, e-mail (facoltativa), governatorato e delegazione, cosa desideri fare e quanti ulivi ti interessano, e le tue note.\nPrenotazione o contratto: numero della carta d'identità e indirizzo, necessari al contratto stesso.\nAccount «Zitounti»: numero di telefono e password cifrata. La tua password non la vediamo mai.\nOfferta di un terreno: il tuo nome e numero, dove si trova il terreno, la superficie e il prezzo richiesto, i documenti che carichi e le coordinate del terreno se le scegli sulla mappa.\nVisita in video: nome e numero WhatsApp, giorno e ora scelti, e le tue note.\nAssistente del sito: la tua domanda e la risposta, più un'impronta cifrata dell'indirizzo IP.\nNotifiche nell'app: l'identificativo del dispositivo, che non contiene né nome né numero.\nIn ogni caso: data e ora, tipo di browser e un'impronta cifrata dell'indirizzo IP — per sicurezza e per verificare le richieste, non per pubblicità."},
 {"title":"La tua posizione","body":"Due casi diversi, che teniamo distinti:\nNell'app, se tocchi «quanto dista?» sulla pagina di un'offerta, chiediamo la posizione al telefono per calcolare la distanza. Il calcolo avviene sul tuo telefono: la posizione non ci arriva, non la salviamo e non la passiamo a nessuno. La chiediamo solo ad app aperta e puoi rifiutare.\nNel modulo «Hai un terreno?», invece, se collochi il terreno sulla mappa o tocchi «sono sul terreno», le coordinate del TERRENO **ci arrivano e vengono salvate** con l'offerta: non possiamo valutare un appezzamento che non sappiamo individuare. Sono le coordinate del terreno offerto, non le tue, e puoi scrivere l'indirizzo a parole."},
 {"title":"I documenti dei terreni","body":"I documenti allegati a un'offerta di terreno sono conservati in uno spazio **privato**: nessun link pubblico, e solo il personale autorizzato di AgriZed (legale, finanza, responsabile agricolo e direzione) può elencarli o scaricarli. Non li pubblichiamo e non li trasmettiamo a terzi.\nAccettiamo solo PDF, JPG e PNG entro un limite di dimensione. Su richiesta li cancelliamo, salvo obblighi di legge."},
 {"title":"L'assistente del sito","body":"Quando interroghi l'assistente, la tua domanda viene inviata a un fornitore di intelligenza artificiale per ottenere la risposta, e conserviamo domanda e risposta per migliorare il servizio e proteggerlo dagli abusi.\nNon scrivere dati sensibili all'assistente — numero di documento, password, dati bancari. Per parlare della tua pratica contattaci direttamente o accedi a «Zitounti»."},
 {"title":"Perché le raccogliamo","body":"Per richiamarti riguardo alla tua richiesta, preparare una stima, predisporre e seguire il contratto e le rate, inviarti i messaggi e le notifiche sulla tua pratica e proteggere il sito dalle richieste fittizie. Non usiamo i tuoi dati per venderti altro e non li vendiamo a nessuno."},
 {"title":"Con chi li condividiamo","body":"Non vendiamo i tuoi dati a nessuno. Li condividiamo solo con i fornitori necessari al servizio: hosting e database, fornitore di SMS, il servizio di notifiche Expo quando le accetti e il fornitore di intelligenza artificiale quando usi l'assistente. Ciascuno riceve solo lo stretto necessario. Oltre a questo, solo su richiesta legittima di un'autorità giudiziaria."},
 {"title":"Per quanto le conserviamo","body":"Contratti e pagamenti: per il tempo imposto dagli obblighi di legge e contabili.\nRichieste di interesse e pratiche clienti: per la durata del rapporto commerciale, poi cancellate in assenza di obblighi di legge.\nOfferte di terreni e relativi documenti: fino alla decisione sull'offerta, poi un anno.\nPrenotazioni di visite: due anni.\nConversazioni con l'assistente: 90 giorni.\nImpronte di indirizzi IP: 12 mesi; sono cifrate e da sole non identificano nessuno.\nIdentificativo delle notifiche: cancellato quando disinstalli l'app o disattivi le notifiche.\nSu tua richiesta, e in assenza di obblighi di legge, cancelliamo i tuoi dati."},
 {"title":"I tuoi diritti","body":"Puoi chiedere di vedere i dati che conserviamo su di te, correggerli o cancellarli, e revocare in qualsiasi momento il consenso a essere contattato. Scrivici all'indirizzo in fondo a questa pagina."},
 {"title":"I bambini","body":"Il servizio è rivolto agli adulti. Non raccogliamo consapevolmente dati su minori; se ne veniamo a conoscenza, li cancelliamo."}
]$json$::jsonb);

update public.settings s
   set value = (select p.body from _priv p where p.locale = 'ar')
 where s.key = 'legal.privacy_sections';

-- A json ARRAY setting is translated whole, one array per language (src/lib/config.ts, settingValue): a
-- partial array would print half a policy. This is the shape site.faq and start.tier_taglines already use.
insert into public.translations (entity, entity_key, field, locale, value, is_draft)
select 'setting', 'legal.privacy_sections', 'value', p.locale, p.body, true
from _priv p
where p.locale <> 'ar'
on conflict (entity, entity_key, field, locale) do update set value = excluded.value;

comment on column public.settings.value is
  'The setting''s value. For legal.privacy_sections the retention periods are OPERATIONAL choices, not legal advice: the ones tied to contracts and accounting say «what the law requires» on purpose, and the rest were given a number so the policy means something. Confirm them with whoever advises the business.';
